const e="Loin des anciennes forêts, ils élevèrent leurs cités vers le ciel.",t="Annales du Royaume d'Uriel",s=["Peuple & Lignée","Hauts-Elfes","Codex #PEU-009"],i=[6,8,9],n="Île d'Uriel, Elogos",o="Maîtrise magique, Erudition, Noblesse",a="175cm - 200cm",l="350",r="« Enfants d'Uriel »",u="Urielar_icone.jpeg",c="Rare / Isolé",d=[{title:"Présentation",type:"text",content:"Les Urielar sont les Elfes établis dans le Royaume d'Uriel sur le continent d'Elogos. Séparés des autres branches elfiques, ils ont développé une haute civilisation magique et raffinée."},{title:"Le Royaume d'Uriel",type:"text",content:"Gouverné par le Roi Faucon et la Reine Azuréenne et protégé par la Garde du Lion Blanc, Uriel forme une puissance politique majeure mais isolée du continent d'Elogos."},{title:"Relations extérieures",type:"politique_list_long",content:[{headline:"Distant",title:"Les Elfes du Vieux Monde",content:"Bien que conscients de leur origine commune, les échanges restent très rares en raison de la distance.",color:"#C29B38"}]},{title:"Aujourd'hui",type:"text",content:"Les Urielar préservent leurs traditions citadines et magiques loin des tumultes des guerres du Vieux Monde."}],g={citation:e,citation_author:t,tags:s,link_articles:i,class:"Elfique",repart:n,trait:o,height:a,age:l,surname:r,image:u,statut:c,sections:d};export{l as age,e as citation,t as citation_author,g as default,a as height,u as image,i as link_articles,n as repart,d as sections,c as statut,r as surname,s as tags,o as trait};
